                        cursor: resizeCorner === 'lower-left' ? 'nesw-resize' : 'nwse-resize',
                        height: HANDLE_SIZE,
                        left: resizeCorner === 'lower-left' ? 0 : undefined,
                        position: 'absolute',
                        right: resizeCorner === 'lower-right' ? 0 : undefined,
                        touchAction: 'none',
                        width: HANDLE_SIZE,
