79	/**
80	 * The message is rebuilt on every render but only reads the worktree list on the failing
81	 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
82	 */
83	function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
84	    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
85	    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
86	    if (context.kind !== 'card' && context.kind !== 'project') {
87	        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for a worktree run'
88	        return `Action "${action.label}" requires card or project context ${reason}`
89	    }
90	    if (context.worktreeError) return context.worktreeError
91	    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
92	    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`
93	
94	    const worktree = Number.parseInt(context.worktree, 10)
95	    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
96	    const record = worktreeService.getRecords()[worktree - 1]
97	    if (!record) return `Configured worktree ${worktree} does not exist`
98	    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`
99	
100	    return null
101	}
102	
103	function worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {
104	    if (context.kind === 'project') return { kind: 'project' }
105	    if ((context.kind === 'card' || context.kind === 'file') && context.file) return { kind: 'card', path: context.file }
106	
107	    return null
108	}
