114	        onClose, onSelectAction, onToggleFullHeight, open, primaryPath, stackPosition, target, titleId,
115	        popupEntryId, readOnlyMessage,
116	    } = props
117	    const theme = useTheme()
118	    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
119	    const settingsContextIdentity = actionContextIdentity(assignmentContext)
120	    const settingsStore = useMemo(
121	        () => assignmentContext.cardInternalId
122	            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
123	            : createSessionActionRunSettingsStore(action.id, settingsContextIdentity),
124	        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
125	    )
126	    const bindings = useMemo(
127	        () => createActionPopupBindings(action, assignmentContext),
128	        [action, assignmentContext],
