130	    const { conversationStore, historyStore, inputStore, resultStore, scheduleStore } = bindings
131	    const runValidationError = worktreeValidationMessage(action, assignmentContext)
132	    const sizeStorageKey = baseContext.kind === 'project'
133	        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY
134	        : CARD_RUN_POPUP_SIZE_STORAGE_KEY
135	    const parsedWorktree = assignmentContext.worktree && /^[1-9]\d*$/u.test(assignmentContext.worktree)
136	        ? Number.parseInt(assignmentContext.worktree, 10)
137	        : null
138	    const worktreeAssignment = {
139	        worktree: parsedWorktree,
140	        worktreeError: assignmentContext.worktreeError ?? null,
141	        worktreeValue: assignmentContext.worktree ?? null,
142	    }
143	    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'
144	        ? worktreeAssignmentTarget(baseContext)
145	        : null
146	    return (
147	        <ResizablePopper
148	            anchorElement={anchorElement}
149	            draggable={isMobile ? false : draggable}
150	            fullHeight={isMobile || fullHeight}
151	            initialSize={{ height: 450, width: 400 }}
152	            labelId={titleId}
153	            onActivate={onActivate}
154	            onClose={onClose}
155	            open={open}
