158	                border: 1,
159	                borderColor: 'divider',
160	                borderRadius: isMobile ? 0 : '14px',
161	                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',
162	                flexDirection: 'column',
163	                height: isMobile ? '100vh !important' : undefined,
164	                left: isMobile ? '0 !important' : undefined,
165	                margin: isMobile ? '0 !important' : undefined,
166	                maxHeight: isMobile ? 'none' : undefined,
167	                maxWidth: isMobile ? 'none' : undefined,
168	                top: isMobile ? '0 !important' : undefined,
169	                transform: isMobile ? 'none !important' : undefined,
170	                width: isMobile ? '100vw !important' : undefined,
171	            }}
172	            resizeFromAllSides
173	            resizeLabel="Resize action popup"
174	            stackPosition={stackPosition}
175	            storageKey={isMobile ? undefined : sizeStorageKey}
176	        >
177	            <MarkdownTypeaheadLayerProvider stackPosition={stackPosition ?? 0}>
178	                <Typography
179	                    id={titleId}
180	                    sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}
181	                >
182	                    {target ? `Run actions for ${target}` : 'Run actions'}
183	                </Typography>
184	                <Box
185	                    data-drag-handle={!isMobile && draggable ? 'true' : undefined}
186	                    sx={{
187	                        borderBottom: 1, borderColor: 'divider', cursor: !isMobile && draggable ? 'move' : undefined,
188	                        display: 'flex', flexDirection: 'column', flexShrink: 0, gap: 1, px: 1.5, py: 1.5,
189	                    }}
190	                >
191	                    <Box data-testid="action-popup-toolbar" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
192	                        {target ? (
193	                            <Box
194	                                component="span"
195	                                sx={{
196	                                    bgcolor: 'custom.primaryBg', borderRadius: '5px', color: 'primary.main', flexShrink: 0,
197	                                    fontFamily: '"Roboto Mono", ui-monospace, monospace', fontSize: 11.5, fontWeight: 600,
198	                                    px: 0.875, py: 0.25,
199	                                }}
200	                            >
201	                                {target}
202	                            </Box>
203	                        ) : null}
204	                        {assignmentTarget && !readOnlyMessage ? (
205	                            <ActionWorktreeSelectorOwner
206	                                actionId={action.id}
207	                                assignment={worktreeAssignment}
208	                                assignmentTarget={assignmentTarget}
209	                                context={assignmentContext}
210	                                primaryPath={primaryPath}
211	                            />
212	                        ) : null}
213	                        {action.type === 'agent' ? (
214	                            <ActionConversationPickerOwner
215	                                actionId={action.id}
216	                                context={assignmentContext}
