268	                                        />
269	                                    ) : null}
270	                                    <ActionLogErrorOwner actionId={action.id} context={assignmentContext} resultStore={resultStore} />
271	                                </Box>
272	                                <ActionConversationChatOwner
273	                                    actionId={action.id}
274	                                    context={assignmentContext}
275	                                    popupEntryId={popupEntryId}
276	                                    store={conversationStore}
277	                                />
278	                                <ActionAgentPromptOwner
279	                                    action={action}
280	                                    context={assignmentContext}
281	                                    conversationStore={conversationStore}
282	                                    historyStore={historyStore}
283	                                    inputStore={inputStore}
284	                                    settingsStore={settingsStore}
